// Тикет #6a86f7d99a8f «עיצוב מוקאפ: תהילים — רשימת פרקים וקטעים» (S-24), проверен 07.10.2026 → עבר QA.
// Опора: реджект 27.09 п.5 (поиск по всему тексту פרק без учёта ניקוד: «רעי לא אחסר» → כ״ג), п.6 («שיר המעלות» → все 15, ק״כ–קל״ד, включая קכ״א);
// S-24 AC5 (узнаваемое имя פריט), AC6 (открытие ведёт к контенту только этого פריט).
// Скрины: d99a8f-4-search-rei (одна карточка «כ״ג · מזמור לדוד יהוה»), d99a8f-4-search-shir-hamaalot (ק״כ «שיר המעלות אל», קכ״א «שיר למעלות אשא» …).
import { driver, expect } from '@wdio/globals';
import { byText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { hebNum, searchField, typeSearch, shown } from '../_lib/app-0710.ts';

const SHIR_HAMAALOT = Array.from({ length: 15 }, (_, i) => hebNum(120 + i));   // ק״כ … קל״ד

describe('Список תהילים: поиск', () => {
  afterEach(async () => {
    if (await shown(searchField())) await typeSearch('');
    await toHome();
  });

  it('TL-02 Поиск «רעי לא אחסר» → только כ״ג и открывает его; «שיר המעלות» → ровно 15 (ק״כ–קל״ד) #6a86f7d99a8f @prod-safe', async () => {
    await goTab('תהילים');

    // 1. Слова из середины פרק, без ניקוד → одна карточка «כ״ג · מזמור לדוד יהוה».
    await typeSearch('רעי לא אחסר');
    await expectVisibleText('כ״ג');
    await expectVisibleText('מזמור לדוד יהוה');
    await expect(byText('אשרי האיש אשר')).not.toBeDisplayed();
    // Открытие → экран «תהילים כ״ג» (S-24 AC6).
    await (await byText('כ״ג')).click();
    await (await byText('תהילים כ״ג')).waitForDisplayed({ timeout: 20000 });
    await driver.back();
    await (await searchField()).waitForDisplayed();

    // 2. «שיר המעלות» → все 15 פרקים 120–134 (включая קכ״א «שיר למעלות»); соседей קי״ט и קל״ה нет.
    await typeSearch('שיר המעלות');
    await expectVisibleText('ק״כ');
    await expectVisibleText('קכ״א');
    for (const label of SHIR_HAMAALOT) await scrollToText(label, 12);
    await expect(byText(hebNum(119))).not.toBeDisplayed();
    await expect(byText(hebNum(135))).not.toBeDisplayed();
  });
});
